WL64=''
import base64,subprocess,json,time,os
wl=base64.b64decode(WL64).decode();p=subprocess.Popen(['/Applications/Wolfram.app/Contents/MacOS/WolframKernel','-noprompt','-run',wl],stdin=subprocess.DEVNULL)
print(json.dumps(dict(event='controller_started',pid=os.getpid(),kernel_pid=p.pid)),flush=True)
forced=False
try:rc=p.wait(timeout=14460)
except subprocess.TimeoutExpired:
 forced=True;p.terminate()
 try:rc=p.wait(timeout=5)
 except subprocess.TimeoutExpired:p.kill();rc=p.wait()
print(json.dumps(dict(event='controller_exit',kernel_pid=p.pid,returncode=rc,reaped=True,forced_timeout=forced)),flush=True)
raise SystemExit(rc)
